 "content": "def transform(grid):
    """Repeat the colored pattern beside a vertical 5-rail upward."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find the strongest vertical 5-rail.
    rails = []
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == 5]
        runs = []
        run = []
        for r in range(h):
            if grid[r][c] == 5:
                run.append(r)
            elif run:
                runs.append(run)
                run = []
        if run:
            runs.append(run)
        if runs:
            best = max(runs, key=len)
            if len(best) >= 2:
                rails.append((len(best), c, best[0], best[-1]))
    if not rails:
        return out
    _, rail_c, rail_top, rail_bottom = max(rails)

    # The rows immediately below the rail's endpoint/within its lower part
    # that contain colored cells to its right form the seed tile.
    active = [any(grid[r][c] != 0 and grid[r][c] != 5
                  for c in range(rail_c + 1, w)) for r in range(h)]
    seed_rows = [r for r, yes in enumerate(active) if yes]
    if not seed_rows:
        return out
    seed_top, seed_bottom = min(seed_rows), max(seed_rows)
    # Use the complete contiguous nonzero seed band at the bottom.
    while seed_top < seed_bottom and not active[seed_top]:
        seed_top += 1
    while seed_bottom > seed_top and not active[seed_bottom]:
        seed_bottom -= 1
    tile = [grid[r][:] for r in range(seed_top, seed_bottom + 1)]

    # Repeat the seed rows upward, preserving the seed's colors and columns.
    fill_top = rail_top
    for r in range(min(seed_top - 1, fill_top), fill_top - 1, -1):
        source = tile[(r - seed_top) % len(tile)]
        for c in range(rail_c + 1, w):
            if source[c] != 0:
                out[r][c] = source[c]
    return out

if __name__ == '__main__':
